const item = $input.first().json || {};
const body = item.body || item;
const telegram_id = String(body.telegram_id || body.from || '').trim();
const chat_id = body.chat_id ?? body.chatId ?? telegram_id;
let text = body.text || body.message || '';
if (typeof text !== 'string') text = text.body || '';
text = String(text || '').trim();
if (!telegram_id) return [];
return [{ json: { telegram_id, chat_id, text } }];

