parameters.jsCode:
const api = $('Call Inventory API').first().json || {};
const telegram_id = api.telegram_id || $('Normalize message').first().json.telegram_id;
const chat_id = $('Normalize message').first().json.chat_id;
const incoming = $input.first().json || {};
let parsed = null;
try {
  let raw = incoming.response ?? incoming.message;
  if (raw && typeof raw === 'object' && raw.action) parsed = raw;
  else if (typeof raw === 'string') {
    const match = raw.match(/\{[\s\S]*\}/);
    parsed = JSON.parse(match ? match[0] : raw);
  }
} catch (e) {
  parsed = null;
}
const action = parsed && parsed.action;
const valid = ['consulta', 'retiro', 'devolucion', 'ingreso', 'traslado'];
if (parsed && valid.includes(String(action || '').toLowerCase())) {
  return [{
    json: {
      retry: true,
      telegram_id,
      chat_id,
      action: String(parsed.action).toLowerCase(),
      where: parsed.where || null,
      from: parsed.from || null,
      elemento: parsed.elemento || null,
      cantidad: parsed.cantidad ?? null,
      quien: parsed.quien || null
    }
  }];
}
return [{ json: { retry: false, telegram_id, chat_id, reply: api.reply, needs_json: true, authorized: api.authorized, ok: false } }];

const data = $input.first().json || {};
const norm = $('Normalize message').first().json;
const telegram_id = String(data.telegram_id || norm.telegram_id || '');
const chat_id = data.chat_id ?? norm.chat_id;
const reply = data.reply || 'No pude procesar el mensaje.';
return [{ json: { ...data, telegram_id, chat_id, reply } }];
